using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class SharedBuildingChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void Verify(){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var nav=god.GetComponent<IslandNavigator>();Require(!nav.world.TreeNavigationPending,"Wait for navigation");var mind=god.GetComponent<CreatureCuriosity>();var sites=god.GetComponent<CreatureConstructionLearning>().sites;var site=sites[0];var stateField=typeof(QuestSlice).GetField("state",Flags);var original=(SliceState)stateField.GetValue(slice);var geometry=site.Capture();var recipe=site.Recipe;bool paused=site.Paused;var position=god.transform.position;var rotation=god.transform.rotation;var held=(CarryItem[])typeof(QuestSlice).GetField("held",Flags).GetValue(slice);Require(held.All(i=>i==null),"Release carried objects");var people=slice.GetComponentsInChildren<VillagerSocial>();var peoplePositions=people.Select(p=>p.transform.position).ToArray();var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,hunger=.1f};
  object Call(string method,params object[] args)=>typeof(CreatureHybrid).GetMethod(method,Flags).Invoke(god,args);
  float Bias(ConstructionBlock b)=>(float)Call("SharedBuildingBias",b.GetComponent<HybridTarget>());
  ConstructionBlock Anchor()=>(ConstructionBlock)typeof(CreatureHybrid).GetField("buildInvitation",Flags).GetValue(god);
  void Place(ConstructionBlock b,Vector3 at){test.Hybrid.time+=1;Require((bool)typeof(QuestSlice).GetMethod("TryGrab",Flags).Invoke(slice,new object[]{1,b.Item}),"Native grab rejected");Physics.SyncTransforms();typeof(QuestSlice).GetMethod("Release",Flags).Invoke(slice,new object[]{1,new Ray(site.World(at+Vector3.up*12),Vector3.down)});Require(b.Attached,"Native drop did not snap");}
  try{
   god.Interrupt("Shared building QA");stateField.SetValue(slice,test);god.NewSeason();slice.SetSanctuaryOpen(false);var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);
   foreach(var person in people){person.ResetTask();person.GetComponent<VillagerExploration>().ResetTask();person.GetComponent<VillagerBlockPlay>().ResetTask();person.GetComponent<VillagerResourceGathering>().Cancel();person.transform.position+=Vector3.up*nav.world.Scale*500;}
   site.Paused=false;site.ResetConstruction();site.Recipe=BuildRecipe.Arch;var block=site.blocks.First(b=>b.Shape==ConstructionShape.Brick);var at=ConstructionPatterns.Plan(BuildRecipe.Arch)[0].position;
   Require(site.Drop(block,site.World(at),site.transform.rotation),"Anonymous stage failed");Require(Anchor()==null,"Anonymous placement invited creature");bool visible=false;
   for(int i=0;i<24;i++){float a=i*Mathf.PI/12;var near=site.World(new Vector3(Mathf.Sin(a)*18,0,Mathf.Cos(a)*18));if(!nav.world.Sample(near,nav.profile,12,out var stage))continue;god.transform.position=nav.world.ProjectFoot(stage,nav.profile);var toward=block.transform.position-god.transform.position;toward.y=0;god.transform.rotation=Quaternion.LookRotation(toward);nav.ResetRoute();if(god.CanSeeCue(block.GetComponent<HybridTarget>())){visible=true;break;}}
   Require(visible,"No visible reachable construction stage");site.ReturnLoose(block);test.Hybrid.time=100;Place(block,at);Require(Anchor()==block&&god.Response==CreatureResponse.Noticed,"Witnessed native snap did not invite");var next=site.blocks.First(b=>!b.Attached&&b.Shape==ConstructionShape.Brick&&b.CanBuild);Require(Bias(next)>.8f&&Bias(block)==0,"Invitation did not transfer to feasible loose pieces");var outside=sites.Where(s=>s!=site).SelectMany(s=>s.blocks).FirstOrDefault(b=>b.CanBuild);if(outside!=null)Require(Bias(outside)==0,"Invitation leaked to another site");
   float until=(float)typeof(CreatureHybrid).GetField("buildInvitationUntil",Flags).GetValue(god);Require(site.Drop(block,block.transform.position,block.transform.rotation,false,"player"),"Repeat snap failed");Require((float)typeof(CreatureHybrid).GetField("buildInvitationUntil",Flags).GetValue(god)<=until,"Stationary repeated Drop refreshed invitation");site.ReturnLoose(block);Place(block,at);
   float pausedAt=test.Hybrid.time;test.paused=true;god.Tick(5);Require(test.Hybrid.time==pausedAt&&Bias(next)==0,"Pause advanced invitation");test.paused=false;Require(Bias(next)>.8f,"Pause consumed invitation");god.Suspend(true);Require(Bias(next)==0,"Suspension retained selection bias");god.Suspend(false);
   block.Item.held=true;block.Grab();block.Item.held=false;Require(Anchor()==null&&Bias(next)==0,"Taking back anchor retained invitation");site.ReturnLoose(block);
   var facing=god.transform.rotation;god.transform.rotation=Quaternion.Euler(0,180,0)*facing;Place(block,at);Require(Anchor()==null,"Unseen rear placement invited construction");god.transform.rotation=facing;site.ReturnLoose(block);test.paused=true;Place(block,at);Require(Anchor()==null,"Paused placement invited construction");test.paused=false;site.ReturnLoose(block);Place(block,at);
   test.Hybrid.time+=46;Require(Bias(next)==0,"Invitation did not expire");site.ReturnLoose(block);Place(block,at);var eligible=site.blocks.First(b=>!b.Attached&&b.Shape==ConstructionShape.Brick&&b.CanBuild);foreach(var a in cooldowns.Keys)a.cooldown=a==eligible.GetComponent<CreatureAffordance>()?0:test.Hybrid.time+1000;
   god.Perceive();var candidates=(System.Collections.Generic.List<CreatureCandidate>)typeof(CreatureHybrid).GetField("candidates",Flags).GetValue(god);Require(candidates.Any(c=>c.target==eligible.GetComponent<HybridTarget>().id&&c.action==CreatureAction.ConstructionPlay&&c.attention>.8f),"Ranked candidate lost shared-build bias");int built=mind.built;bool selected=false;for(int i=0;i<1600&&mind.built==built;i++){god.Tick(.05f);site.Advance(.02f);selected|=god.Owner==CreatureHybrid.ActionOwner.Curiosity&&test.Hybrid.intention.action==CreatureAction.ConstructionPlay&&test.Hybrid.intention.source==EvidenceSource.PlayerPlacement;}
   Require(selected&&mind.built==built+1&&eligible.Attached&&eligible.creatureBuilt,"Utility-selected native construction did not complete: "+god.Explanation+" / "+mind.Current);Require(test.placeContributions.records.Any(r=>r.actor=="player")&&test.placeContributions.records.Any(r=>r.actor=="creature"),"Shared placement actors were lost");
   test.construction=site.Capture();var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(saved.Valid(),"Shared construction state invalid");stateField.SetValue(slice,saved);Require(Bias(next)==0,"Invitation crossed save reload");site.Restore(saved.construction);Require(site.Snapped>=2&&saved.placeContributions.records.Length==test.placeContributions.records.Length,"Reload lost geometry or replayed receipts");god.NewSeason();Require(Anchor()==null,"Season reset kept invitation");
   Debug.Log("BWVR_SHARED_BUILDING_PASS: native player snap, witnessed-only receipt, bounded same-yard candidate bias, duplicate/held/pause/suspend/expiry gates, utility-selected native carry/place, separate player/creature attribution and restored geometry without transient invitation");
  }finally{god.Interrupt("Shared building QA complete");Call("ClearSharedBuilding");held[1]=null;foreach(var b in site.blocks)b.Item.held=false;site.Recipe=recipe;site.Restore(geometry);site.Paused=paused;for(int i=0;i<people.Length;i++)people[i].transform.position=peoplePositions[i];foreach(var pair in cooldowns)pair.Key.cooldown=pair.Value;god.transform.SetPositionAndRotation(position,rotation);nav.ResetRoute();stateField.SetValue(slice,original);}
 }
}
}
